"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[9376],{9425(t,e,a){a.r(e),a.d(e,{assets:()=>l,contentTitle:()=>c,default:()=>h,frontMatter:()=>d,metadata:()=>r,toc:()=>p});const r=JSON.parse('{"id":"part2-backend-platform-security/index","title":"Part II \u2014 Backend, Platform & Security","description":"The platform layer that the agent and ML systems sit on top of: FastAPI basics, the request lifecycle, Pydantic data contracts, concurrency & user isolation, background work and retries, the full authentication stack...","source":"@site/docs/part2-backend-platform-security/index.mdx","sourceDirName":"part2-backend-platform-security","slug":"/part2-backend-platform-security/overview","permalink":"/tutorials/part2-backend-platform-security/overview","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"frontMatter":{"title":"Part II \u2014 Backend, Platform & Security","slug":"/part2-backend-platform-security/overview","description":"The platform layer that the agent and ML systems sit on top of: FastAPI basics, the request lifecycle, Pydantic data contracts, concurrency & user isolation, background work and retries, the full authentication stack...","sidebar_label":"Part overview","pagination_label":"Part overview","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"11. Provisioning, services, scale","permalink":"/tutorials/part1-enterprise-ai-delivery/11-provisioning-services-scale"},"next":{"title":"1. FastAPI and Uvicorn basics","permalink":"/tutorials/part2-backend-platform-security/01-fastapi-uvicorn-basics"}}');var n=a(4848),i=a(8453),s=a(8172);const o=JSON.parse('{"sourcePath":"part2-backend-platform-security/index.html","route":"/part2-backend-platform-security/overview","kind":"part","partId":"part2","partLabel":"Part II - Backend, Platform & Security","accent":"teal","heading":"Part II \u2014 Backend, Platform & Security","title":"Part II \u2014 Backend, Platform & Security","description":"The platform layer that the agent and ML systems sit on top of: FastAPI basics, the request lifecycle, Pydantic data contracts, concurrency & user isolation, background work and retries, the full authentication stack...","readingMinutes":2,"bodyClass":"","normalizeMath":false,"toc":[{"id":"chapters-in-order","label":"Chapters in order"},{"id":"concept-map","label":"Concept Map"}],"html":"<p>The platform layer that the agent and ML systems sit on top of: FastAPI\\nbasics, the request lifecycle, Pydantic data contracts, concurrency &amp; user\\nisolation, background work and retries, the full authentication stack\\n(SSO/OAuth2/OIDC/PKCE/JWT vs opaque), workload identity vs end\u2011user identity,\\nmulti\u2011tenant isolation, external integrations, and the GitHub governance that\\nkeeps the codebase shippable.</p>\\n\\n<div class=\\"tr-tip\\">\\n  <strong>Reading order tip</strong>\\n  Chapters 1\u20136 are the FastAPI runtime and data-contract story. Chapter 4 is\\n  the Pydantic bridge between raw HTTP/JSON and typed Python objects. Chapters\\n  7\u201311 are the auth story, ordered from OIDC basics through modern\\n  sender-constrained patterns. Chapters 12\u201314 then merge the identity concepts\\n  with tenancy, IAM, and GCP workload identity. Chapters 15\u201316 cover external\\n  integrations and GitHub governance.\\n</div>\\n\\n<div class=\\"tr-note\\">\\n  <strong>Prerequisites</strong>\\n  Comfortable with Python 3, basic HTTP, and the command line. No prior\\n  FastAPI knowledge required. The auth chapters (7\u201316) are theory + code\\n  and stand on their own; you do not need to read Part I first.\\n</div>\\n\\n<h2 id=\\"chapters-in-order\\">Chapters in order</h2>\\n<ol>\\n  <li><a href=\\"/tutorials/part2-backend-platform-security/01-fastapi-uvicorn-basics\\">FastAPI &amp; Uvicorn basics</a></li>\\n  <li><a href=\\"/tutorials/part2-backend-platform-security/02-http-methods\\">HTTP methods</a></li>\\n  <li><a href=\\"/tutorials/part2-backend-platform-security/03-fastapi-request-mapping\\">FastAPI request mapping</a></li>\\n  <li><a href=\\"/tutorials/part2-backend-platform-security/04-pydantic-data-models\\">Pydantic data models: classes, dataclasses, validation, settings, APIs, and LLM outputs</a></li>\\n  <li><a href=\\"/tutorials/part2-backend-platform-security/04-concurrency-user-isolation\\">Concurrency, backpressure, and per-request isolation</a></li>\\n  <li><a href=\\"/tutorials/part2-backend-platform-security/05-background-tasks-and-retries\\">Background tasks &amp; retries</a></li>\\n  <li><a href=\\"/tutorials/part2-backend-platform-security/06-sso-oauth2-oidc-primer\\">SSO / OAuth2 / OIDC primer</a></li>\\n  <li><a href=\\"/tutorials/part2-backend-platform-security/07-oidc-oauth2-pkce-fastapi\\">OIDC + OAuth2 + PKCE in FastAPI</a></li>\\n  <li><a href=\\"/tutorials/part2-backend-platform-security/08-registering-new-users\\">First login and user provisioning</a></li>\\n  <li><a href=\\"/tutorials/part2-backend-platform-security/09-authentication-deep-dive\\">Authentication deep dive</a></li>\\n  <li><a href=\\"/tutorials/part2-backend-platform-security/15-modern-auth-additions\\">Modern auth additions: Passkeys, DPoP, mTLS, token exchange</a></li>\\n  <li><a href=\\"/tutorials/part2-backend-platform-security/10-enduser-vs-workload-identity\\">End\u2011user vs workload identity</a></li>\\n  <li><a href=\\"/tutorials/part2-backend-platform-security/12-tenant-iam-ad-groups\\">Tenant isolation, IAM &amp; AD groups</a></li>\\n  <li><a href=\\"/tutorials/part2-backend-platform-security/11-gcp-workload-identity\\">GCP workload identity</a></li>\\n  <li><a href=\\"/tutorials/part2-backend-platform-security/13-external-service-integration\\">Cross-cloud service integration</a></li>\\n  <li><a href=\\"/tutorials/part2-backend-platform-security/14-github-governance\\">GitHub governance &amp; CI</a></li>\\n</ol>\\n\\n<div class=\\"tr-note\\">\\n  <strong>Identity path</strong>\\n  Chapters 12 and 13 intentionally cover related identity ideas from different\\n  angles: Chapter 12 separates end-user identity, workload identity, and IAM;\\n  Chapter 13 applies the same model to tenant isolation, AD groups, and\\n  bootstrap policy. Read them together before the GCP implementation chapter.\\n</div>\\n\\n<h2 id=\\"concept-map\\">Concept Map</h2>\\n<table>\\n  <thead>\\n    <tr>\\n      <th>Cluster</th>\\n      <th>Primary chapter</th>\\n      <th>How the related chapters should be read</th>\\n    </tr>\\n  </thead>\\n  <tbody>\\n    <tr>\\n      <td>FastAPI runtime and HTTP request handling</td>\\n      <td><a href=\\"/tutorials/part2-backend-platform-security/03-fastapi-request-mapping\\">Ch. 3</a></td>\\n      <td>Ch. 1 introduces the server, Ch. 2 owns verb semantics, Ch. 3 owns the exact HTTP-to-FastAPI mapping, and Ch. 4 explains the Pydantic model layer used for request/response contracts.</td>\\n    </tr>\\n    <tr>\\n      <td>Pydantic data contracts, validation, serialization, settings, and LLM output parsing</td>\\n      <td><a href=\\"/tutorials/part2-backend-platform-security/04-pydantic-data-models\\">Ch. 4</a></td>\\n      <td>Starts from Python classes and dataclasses, then explains why Pydantic exists and how it is used across FastAPI, config, queues, external APIs, and structured LLM outputs.</td>\\n    </tr>\\n    <tr>\\n      <td>OAuth2/OIDC/PKCE/JWT/opaque/API key authentication</td>\\n      <td><a href=\\"/tutorials/part2-backend-platform-security/09-authentication-deep-dive\\">Ch. 10</a></td>\\n      <td>Ch. 7 primes the vocabulary, Ch. 8 implements it in FastAPI, Ch. 9 covers first-login provisioning, Ch. 11 adds modern extensions.</td>\\n    </tr>\\n    <tr>\\n      <td>End-user identity, tenancy, IAM, groups, workload identity</td>\\n      <td><a href=\\"/tutorials/part2-backend-platform-security/10-enduser-vs-workload-identity\\">Ch. 12</a></td>\\n      <td>Ch. 13 applies the model to AD/Workspace group gates and tenant bootstrap policy; Ch. 14 implements it on GCP.</td>\\n    </tr>\\n    <tr>\\n      <td>External integration and governance</td>\\n      <td><a href=\\"/tutorials/part2-backend-platform-security/13-external-service-integration\\">Ch. 15</a> and <a href=\\"/tutorials/part2-backend-platform-security/14-github-governance\\">Ch. 16</a></td>\\n      <td>Ch. 15 owns cross-cloud credentials, federation, HTTP reliability, and data-governance boundaries; Ch. 16 owns repository and CI enforcement.</td>\\n    </tr>\\n  </tbody>\\n</table>"}'),d={title:"Part II \u2014 Backend, Platform & Security",slug:"/part2-backend-platform-security/overview",description:"The platform layer that the agent and ML systems sit on top of: FastAPI basics, the request lifecycle, Pydantic data contracts, concurrency & user isolation, background work and retries, the full authentication stack...",sidebar_label:"Part overview",pagination_label:"Part overview",hide_title:!0,hide_table_of_contents:!0},c=void 0,l={},p=[];function u(t){return(0,n.jsx)(s.A,{content:o})}function h(t={}){const{wrapper:e}={...(0,i.R)(),...t.components};return e?(0,n.jsx)(e,{...t,children:(0,n.jsx)(u,{...t})}):u()}}}]);